package com.example.zephyrcampsites

// The following code was generated by OpenAI, ChatGPT,
// "Create a simple campsite location and registration view using
// Jetpack Compose with map coordinates, availability, and publishing",
// 2026-11-05.

import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import com.google.firebase.firestore.GeoPoint
import java.util.Date
import android.net.Uri
import androidx.activity.compose.rememberLauncherForActivityResult
import androidx.activity.result.PickVisualMediaRequest
import androidx.activity.result.contract.ActivityResultContracts

@Composable
fun CampsiteLocationView(
    onPublish: (GeoPoint, Date, Date) -> Unit,
    onBack: () -> Unit
) {
    var latitude by remember { mutableStateOf("") }
    var longitude by remember { mutableStateOf("") }
    var startDate by remember { mutableStateOf<Date?>(null) }
    var endDate by remember { mutableStateOf<Date?>(null) }
    var showCalendar by remember { mutableStateOf(false) }
    var selectedImages by remember { mutableStateOf<List<Uri>>(emptyList()) }
    val imagePicker = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.PickMultipleVisualMedia(5)
    ) {
        images ->
        selectedImages = images
    }
    val lat = latitude.toDoubleOrNull()
    val lon = longitude.toDoubleOrNull()

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        Text(
            "REGISTER CAMPSITE",
            style = MaterialTheme.typography.titleLarge
        )

        Text("Map Location")

        OutlinedTextField(
            value = latitude,
            onValueChange = { latitude = it },
            label = { Text("Latitude") },
            modifier = Modifier.fillMaxWidth()
        )

        OutlinedTextField(
            value = longitude,
            onValueChange = { longitude = it },
            label = { Text("Longitude") },
            modifier = Modifier.fillMaxWidth()
        )

        Text("Availability")
        // The following code was generated by OpenAI, ChatGPT,
        // "Create a button to select and remove campsite photos
        // using Android Photo Picker in Jetpack Compose",
        // 2026-11-05.
        Text("Campsite Photos")

        Button(
            onClick = {
                imagePicker.launch(
                    PickVisualMediaRequest(
                        ActivityResultContracts.PickVisualMedia.ImageOnly
                    )
                )
            }
        ) {
            Text("ADD PHOTOS")
        }

        if (selectedImages.isNotEmpty()) {
            Text("${selectedImages.size} photos selected")

            TextButton(
                onClick = {
                    selectedImages = emptyList()
                }
            ) {
                Text("REMOVE PHOTOS")
            }
        }


        Button(onClick = { showCalendar = true }) {
            Text("SET DATES")
        }

        if (startDate != null && endDate != null) {
            Text("From: $startDate")
            Text("To: $endDate")
        }

        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(
                enabled = lat != null &&
                        lat in -90.0..90.0 &&
                        lon != null &&
                        lon in -180.0..180.0 &&
                        startDate != null &&
                        endDate != null,
                onClick = {
                    onPublish(
                        GeoPoint(lat!!, lon!!),
                        startDate!!,
                        endDate!!
                    )
                }
            ) {
                Text("PUBLISH")
            }

            OutlinedButton(onClick = onBack) {
                Text("BACK")
            }
        }
    }

    if (showCalendar) {
        CampsiteAvailabilityView(
            onSave = { start, end ->
                startDate = start
                endDate = end
                showCalendar = false
            },
            onBack = { showCalendar = false }
        )
    }
}